// The 'store' service: one key-value interface for the plugins, the backend is the service's. A
// plugin asks for an area (its name), and gets and sets JSON values by key in it. Reads and writes
// are synchronous: they go to a cache in memory, which the backend fills before the service is
// provided (a plugin with `inject: ['store']` waits on cordis, so it never sees an unloaded store)
// and which writes go through to the backend from.
//
// - local, now: the page's localStorage, one entry per key (`tilr.<area>.<key>`, the value as
//   JSON), so a change to one key does not rewrite the area. An area is read on its first
//   `area()`, which is synchronous too. Every access is in a try (private mode, a full quota): a
//   write that fails keeps the cached value for this page and warns once per area. Another tab's
//   writes arrive as the window's `storage` event and are reported like this page's.
// - app, later: the Mac app's store, through `webkit.messageHandlers.tilrStore` (as audio does
//   with tilrAudio): secure areas in the Keychain. Async: the service loads every area before it
//   provides 'store'.
// - cloud, later: Tilr Cloud, other devices' changes reported as another tab's are.
//
// The core's plugins kept their state under their own localStorage keys before the store
// (`tilr-layout`, `tilr-panel`, `tilr-clock-zone`); the local backend moves each into its area
// the first time that area is read (LEGACY below), so a saved layout survives the upgrade.
//
// A fresh page is seeded: when the backend holds nothing yet (no `tilr.*` key in localStorage)
// and the site's plugins.json names a seed (`"store": "store.json"`, which `tilr app new --from`
// writes with the template's store.json), the service writes that file (`{ area: { key: value } }`)
// through the backend before it provides 'store'. Once: after that the page has keys and the file
// is ignored; `localStorage.clear()` and a reload seed again. A site without the field is not
// asked for a file (no 404 on every fresh page).
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { Json, Store as StoreApi, StoreArea, TilrPluginClass } from 'tilr'

/** The prefix of the local backend's localStorage keys. */
export const PREFIX = 'tilr.'

/** The old localStorage keys of the core's plugins → the area and key they moved to. */
export const LEGACY: Record<string, { area: string, key: string }> = {
  'tilr-layout': { area: 'layout', key: 'data' },
  'tilr-panel': { area: 'panel', key: 'state' },
  'tilr-clock-zone': { area: 'header', key: 'zone' },
}

/** A value as the cache holds it: parsed, and the JSON it came from (to tell a real change). */
interface Entry { value: Json, text: string }

/** A change the backend reports from elsewhere: `text` null is a delete. */
export type Change = { area: string, key: string, text: string | null }

/** What a backend does. The cache above it is the service's; a backend only loads an area and
 *  writes through. */
export interface Backend {
  readonly name: string
  /** Every key of the area, as JSON text. */
  load(area: string, secure: boolean): Map<string, string>
  /** The names of the areas that have keys (or old keys to move in), loaded or not. */
  areas(): string[]
  /** Writes one key (`text` null: deletes it). False when the backend refused. */
  write(area: string, key: string, text: string | null, secure: boolean): boolean
  /** Changes from elsewhere (another tab, another device); returns the off. `null` from a
   *  backend that lost track (another tab cleared everything): reload the loaded areas. */
  listen(on: (change: Change | null) => void): () => void
}

/** localStorage's part the local backend uses. */
export type StorageLike = Pick<Storage, 'getItem' | 'setItem' | 'removeItem' | 'key' | 'length'>

/** The local backend: localStorage, `tilr.<area>.<key>` → the value's JSON. `events` is where
 *  another tab's `storage` events arrive (the window). */
export class LocalBackend implements Backend {
  readonly name = 'local'
  private storage: StorageLike | null
  private events: EventTarget | null

  constructor(storage: StorageLike | null, events: EventTarget | null) {
    this.storage = storage
    this.events = events
  }

  load(area: string): Map<string, string> {
    const out = new Map<string, string>()
    const storage = this.storage
    if (!storage) return out
    try {
      this.migrate(area)
      const prefix = `${PREFIX}${area}.`
      for (let i = 0; i < storage.length; i += 1) {
        const name = storage.key(i)
        if (name === null || !name.startsWith(prefix)) continue
        const text = storage.getItem(name)
        if (text !== null) out.set(name.slice(prefix.length), text)
      }
    } catch {}
    return out
  }

  areas(): string[] {
    const out = new Set<string>()
    const storage = this.storage
    if (!storage) return []
    try {
      for (let i = 0; i < storage.length; i += 1) {
        const name = storage.key(i)
        const parsed = name === null ? null : parse(name)
        if (parsed) out.add(parsed.area)
      }
      for (const [old, to] of Object.entries(LEGACY)) if (storage.getItem(old) !== null) out.add(to.area)
    } catch {}
    return [...out].sort()
  }

  write(area: string, key: string, text: string | null): boolean {
    if (!this.storage) return false
    try {
      if (text === null) this.storage.removeItem(`${PREFIX}${area}.${key}`)
      else this.storage.setItem(`${PREFIX}${area}.${key}`, text)
      return true
    } catch { return false }
  }

  listen(on: (change: Change | null) => void): () => void {
    const events = this.events
    if (!events) return () => {}
    const listener = (event: Event) => {
      const { key: name, newValue } = event as StorageEvent
      if (name === null) return on(null)
      const change = parse(name)
      if (change) on({ ...change, text: newValue })
    }
    events.addEventListener('storage', listener)
    return () => events.removeEventListener('storage', listener)
  }

  /** The area's old keys (LEGACY), moved to its own unless it has them already. A value that is
   *  not JSON stays where it was. */
  private migrate(area: string): void {
    const storage = this.storage
    if (!storage) return
    for (const [old, to] of Object.entries(LEGACY)) {
      if (to.area !== area) continue
      const text = storage.getItem(old)
      if (text === null) continue
      const name = `${PREFIX}${area}.${to.key}`
      if (storage.getItem(name) === null) {
        try { JSON.parse(text) } catch { continue }
        storage.setItem(name, text)
      }
      storage.removeItem(old)
    }
  }
}

/** `tilr.<area>.<key>` → area and key; null for any other key. */
export function parse(name: string): { area: string, key: string } | null {
  if (!name.startsWith(PREFIX)) return null
  const rest = name.slice(PREFIX.length)
  const dot = rest.indexOf('.')
  if (dot <= 0 || dot === rest.length - 1) return null
  return { area: rest.slice(0, dot), key: rest.slice(dot + 1) }
}

type Watcher = { key: string | null, listener: (key: string, value: Json | undefined) => void }

/** One area as the cache holds it. */
class Area {
  readonly name: string
  secure: boolean
  entries: Map<string, Entry>
  watchers = new Set<Watcher>()
  /** A failed write was warned about. */
  warned = false

  constructor(name: string, secure: boolean, texts: Map<string, string>) {
    this.name = name
    this.secure = secure
    this.entries = new Map()
    for (const [key, text] of texts) {
      try { this.entries.set(key, { value: JSON.parse(text) as Json, text }) } catch {}
    }
  }
}

/**
 * The cache over a backend: the areas, their watchers, the writes through. What the service is,
 * minus cordis (the tests drive it directly). `emit` is the bus ('store/change').
 */
export class Cache {
  readonly backend: Backend
  private areas = new Map<string, Area>()
  private emit: (area: string, key: string, value: Json | undefined) => void

  constructor(backend: Backend, emit: (area: string, key: string, value: Json | undefined) => void = () => {}) {
    this.backend = backend
    this.emit = emit
  }

  /** The area, loaded on its first call. A later `secure` makes it secure (never the reverse). */
  open(name: string, secure = false): Area {
    if (typeof name !== 'string' || !name || name.includes('.')) throw new Error(`store: bad area name '${String(name)}' (non-empty, no dots)`)
    let area = this.areas.get(name)
    if (!area) this.areas.set(name, area = new Area(name, secure, this.backend.load(name, secure)))
    else if (secure) area.secure = true
    return area
  }

  get(area: Area, key: string): Json | undefined {
    return area.entries.get(String(key))?.value
  }

  set(area: Area, key: string, value: Json): void {
    key = String(key)
    const text = JSON.stringify(value) as string | undefined
    // undefined (or a function) says nothing in JSON: that is a delete.
    if (text === undefined) return this.delete(area, key)
    if (area.entries.get(key)?.text === text) return
    area.entries.set(key, { value: JSON.parse(text) as Json, text })
    this.through(area, key, text)
    this.changed(area, key)
  }

  delete(area: Area, key: string): void {
    key = String(key)
    if (!area.entries.has(key)) return
    area.entries.delete(key)
    this.through(area, key, null)
    this.changed(area, key)
  }

  keys(area: Area): string[] {
    return [...area.entries.keys()]
  }

  watch(area: Area, key: string | null, listener: Watcher['listener']): () => void {
    const watcher: Watcher = { key: key === null ? null : String(key), listener }
    area.watchers.add(watcher)
    return () => { area.watchers.delete(watcher) }
  }

  /** A change from elsewhere (the backend's `listen`). An area not loaded here is nobody's
   *  concern: it is read fresh when opened. */
  receive(change: Change | null): void {
    if (change === null) {
      for (const area of this.areas.values()) this.reload(area)
      return
    }
    const area = this.areas.get(change.area)
    if (!area) return
    const entry = area.entries.get(change.key)
    if (change.text === null) {
      if (!entry) return
      area.entries.delete(change.key)
    } else {
      if (entry?.text === change.text) return
      let value: Json
      try { value = JSON.parse(change.text) as Json } catch { return }
      area.entries.set(change.key, { value, text: change.text })
    }
    this.changed(area, change.key)
  }

  /** Every area the backend has, and every area opened here: key → value. An opened area is
   *  as the cache has it (a write the backend refused included); an empty one is left out. */
  dump(): Record<string, Record<string, Json>> {
    const out: Record<string, Record<string, Json>> = {}
    for (const name of [...new Set([...this.backend.areas(), ...this.areas.keys()])].sort()) {
      const values: Record<string, Json> = {}
      const area = this.areas.get(name)
      if (area) for (const [key, entry] of area.entries) values[key] = entry.value
      else {
        for (const [key, text] of this.backend.load(name, false)) {
          try { values[key] = JSON.parse(text) as Json } catch {}
        }
      }
      if (Object.keys(values).length) out[name] = values
    }
    return out
  }

  /** Forgets the watchers (the service is going; the plugins that added them go with it). */
  clear(): void {
    for (const area of this.areas.values()) area.watchers.clear()
  }

  private reload(area: Area): void {
    const fresh = new Area(area.name, area.secure, this.backend.load(area.name, area.secure))
    const before = area.entries
    area.entries = fresh.entries
    for (const key of new Set([...before.keys(), ...fresh.entries.keys()])) {
      if (before.get(key)?.text !== fresh.entries.get(key)?.text) this.changed(area, key)
    }
  }

  private through(area: Area, key: string, text: string | null): void {
    if (this.backend.write(area.name, key, text, area.secure) || area.warned) return
    area.warned = true
    console.warn(`store: the ${this.backend.name} backend refused a write to '${area.name}' (kept for this page only)`)
  }

  private changed(area: Area, key: string): void {
    const value = area.entries.get(key)?.value
    for (const watcher of [...area.watchers]) {
      if (watcher.key !== null && watcher.key !== key) continue
      try { watcher.listener(key, value) } catch (error) { console.error(error) }
    }
    this.emit(area.name, key, value)
  }
}

/** Seeds an empty backend from the file the site's plugins.json (at `manifest`) names as
 *  `store` (relative to it; `{ area: { key: value } }`): every key written through as JSON.
 *  Nothing when the backend has any area already, when plugins.json names no seed, or when a file
 *  is not there (404, no network, not JSON). Resolves to the number of keys written, null when
 *  it did not seed. */
export async function seed(backend: Backend, manifest: URL | string, fetcher: typeof fetch = globalThis.fetch): Promise<number | null> {
  if (backend.areas().length) return null
  let data: unknown
  try {
    const list = await fetcher(manifest, { cache: 'no-store' })
    if (!list.ok) return null
    const { store } = await list.json() as { store?: unknown }
    if (typeof store !== 'string' || !store) return null
    const response = await fetcher(new URL(store, list.url || manifest), { cache: 'no-store' })
    if (!response.ok) return null
    data = await response.json()
  } catch { return null }
  if (!data || typeof data !== 'object' || Array.isArray(data)) return null
  let n = 0
  for (const [area, values] of Object.entries(data as Record<string, unknown>)) {
    if (!area || area.includes('.') || !values || typeof values !== 'object' || Array.isArray(values)) continue
    for (const [key, value] of Object.entries(values as Record<string, unknown>)) {
      const text = JSON.stringify(value) as string | undefined
      if (!key || text === undefined) continue
      if (backend.write(area, key, text, false)) n += 1
    }
  }
  return n
}

/** What a caller holds: an area, and the caller's context, whose effects its watchers become. */
class Handle implements StoreArea {
  private cache: Cache
  private area: Area
  private ctx: Context | null

  constructor(cache: Cache, area: Area, ctx: Context | null) {
    this.cache = cache
    this.area = area
    this.ctx = ctx
  }

  get name(): string { return this.area.name }

  get<T extends Json = Json>(key: string): T | undefined {
    return this.cache.get(this.area, key) as T | undefined
  }

  set(key: string, value: Json): void { this.cache.set(this.area, key, value) }
  delete(key: string): void { this.cache.delete(this.area, key) }
  keys(): string[] { return this.cache.keys(this.area) }

  watch(key: string | null, listener: (key: string, value: Json | undefined) => void): () => void {
    const off = this.cache.watch(this.area, key, listener)
    if (!this.ctx) return off
    // An effect of the caller, so the watcher leaves with it; the returned function removes it
    // earlier (and the effect with it). A caller that is not running keeps it as is.
    try {
      const dispose = this.ctx.effect(() => off, `store: watch('${this.area.name}')`)
      return () => { void dispose() }
    } catch {
      return off
    }
  }
}

/** localStorage, or null where reading it throws (a sandboxed frame). */
function local(): StorageLike | null {
  try { return globalThis.localStorage ?? null } catch { return null }
}

class StoreService extends Service implements StoreApi {
  static provide = 'store'
  static author = 'dan'
  static tags = ['core']
  static version = __TILR_VERSION__
  // Layout, the panel and the header keep their state here: switching it off would take them along.
  static locked = true

  declare state: { cache: Cache }

  constructor(ctx: Context) {
    super(ctx, StoreService.provide)
    // The only backend yet. An async one (app, cloud) would load every area first in
    // [Service.init] (cordis waits on it before the plugins that inject 'store' start).
    const cache = new Cache(new LocalBackend(local(), globalThis.window ?? null), (area, key, value) => ctx.emit('store/change', area, key, value))
    this.state = { cache }
    ctx.effect(() => {
      const off = cache.backend.listen(change => cache.receive(change))
      return () => {
        off()
        cache.clear()
      }
    }, 'store: changes from elsewhere')
  }

  /** A fresh page is seeded from the file plugins.json names (site/plugins/store/index.js →
   *  site/plugins.json) before anyone injecting 'store' starts. */
  async [Service.init](): Promise<void> {
    const n = await seed(this.state.cache.backend, new URL('../../plugins.json', import.meta.url))
    if (n !== null) console.info(`store: seeded ${n} keys from the site's seed`)
  }

  get backend(): string {
    return this.state.cache.backend.name
  }

  area(name: string, options?: { secure?: boolean }): StoreArea {
    // this.ctx is the caller's context: the handle's watchers are its effects.
    return new Handle(this.state.cache, this.state.cache.open(name, options?.secure === true), this.ctx)
  }

  dump(): Record<string, Record<string, Json>> {
    return this.state.cache.dump()
  }
}

export default StoreService satisfies TilrPluginClass
